import {
  Collection,
  GridList as AriaGridList,
  GridListHeader as AriaGridListHeader,
  GridListItem as AriaGridListItem,
  GridListLoadMoreItem as AriaGridListLoadMoreItem,
  GridListSection as AriaGridListSection,
  Text,
} from "react-aria-components";
import type {
  GridListItemProps as AriaGridListItemProps,
  GridListLoadMoreItemProps as AriaGridListLoadMoreItemProps,
  GridListProps as AriaGridListProps,
  GridListSectionProps as AriaGridListSectionProps,
} from "react-aria-components";
import type { CSSProperties, ComponentProps, ReactNode, Ref } from "react";
import { Checkbox } from "./Checkbox";
import "./GridList.css";

type AriaGridListHeaderProps = ComponentProps<typeof AriaGridListHeader>;

export interface GridListProps<T extends object = object>
  extends Omit<AriaGridListProps<T>, "className"> {
  /**
   * `flat`: rows on the list's own surface, bounded only by their hover, focus and selected paints.
   * `contained`: each row its own card (the surface, a decorative edge and the surface pair's padding
   * and corner), the rows parted by a gap, for a short list of options that each lead somewhere.
   * `grouped`: one box around all the rows (the surface pair's corner, a decorative edge), the rows
   * parted by hairlines, for a short choice sheet whose rows belong together.
   *
   * @default "flat"
   */
  variant?: "flat" | "contained" | "grouped";
  /**
   * With `layout="grid"` (React Aria's: the items flow into as many columns as fit, and the arrow
   * keys move in two dimensions), the narrowest a column may get, as a CSS length. Each item then
   * stacks its parts vertically, a tile rather than a row. Ignored in the default `stack` layout.
   *
   * @default "12rem"
   */
  minItemWidth?: string;
  /**
   * How wide each row's `leading` slot is, in the default `stack` layout. `content`: each row's
   * slot hugs its own content, so a row whose leading is wider starts its text further in.
   * `shared`: every row's slot is as wide as the widest one in the list (rows are subgrids of one
   * column grid), so the column after it starts at one x on every row — for leading values of
   * varying length, such as amounts ("7GB", "100GB"). The slot's content starts its column. Rows
   * stay rows: the grid is layout only, and the keyboard and ARIA are React Aria's, unchanged.
   * Ignored in `layout="grid"`.
   *
   * @default "content"
   */
  leadingWidth?: "content" | "shared";
  /** Additional class. sd-grid-list is always retained. */
  className?: string;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

const widthVar = (width: string) =>
  ({ "--sd-grid-list-min-item-width": width }) as CSSProperties;

export function GridList<T extends object = object>({
  variant = "flat",
  minItemWidth = "12rem",
  leadingWidth = "content",
  className,
  style,
  renderEmptyState,
  ...props
}: GridListProps<T>) {
  return (
    <AriaGridList
      {...props}
      /* An empty state given as words is a text part of its own: a bare string took no type role,
         so it stood at 0 while every other text stands one inset in (component-contract.md §6
         rule 8). Medium at every size, as a collection's empty message is (§7), muted as an empty
         line is (text colour roles, row 4). Words are wrapped; an element the consumer drew (a
         ComboBox's own empty part) is its own. */
      renderEmptyState={
        renderEmptyState &&
        ((p) => {
          const empty = renderEmptyState(p);
          return typeof empty === "string" || typeof empty === "number" ? <div className="sd-grid-list__empty sd-type-body-medium">{empty}</div> : empty;
        })
      }
      // Always injected: `layout` may arrive through GridListContext rather than this prop, and the
      // stack layout never reads the variable.
      style={
        typeof style === "function"
          ? (renderProps) => ({ ...widthVar(minItemWidth), ...style(renderProps) })
          : { ...widthVar(minItemWidth), ...style }
      }
      data-variant={variant}
      data-leading-width={leadingWidth}
      className={className ? `sd-grid-list ${className}` : "sd-grid-list"}
    />
  );
}

export interface GridListItemProps<T extends object = object>
  extends Omit<AriaGridListItemProps<T>, "className"> {
  /** Leading slot before the text — a generic region that holds an icon, number,
   *  avatar, image, or swatch (optional). Sized to its content (a bare icon defaults to
   *  the icon-medium size; an avatar/image sizes itself), vertically centered. Decorative
   *  by default (`aria-hidden`) since the row's accessible name comes from `textValue`. */
  leading?: ReactNode;
  /** Secondary line under the primary label — makes the row a two-line rich item.
   *  `children` render as the visual title; this renders in RAC's `slot="description"`
   *  and is folded into the row's accessible name via `aria-labelledby`. The name
   *  itself comes from `textValue` (auto-derived from string `children`) — pass an
   *  explicit `textValue` when the label isn't plain text. */
  description?: ReactNode;
  /** Trailing accessory pinned to the row end — a chevron, metadata, or (GridList
   *  permits interactive children) an action control. Decorative/metadata trailing
   *  content is NOT part of the row's accessible name; if it carries meaning (e.g. a
   *  shortcut hint), fold that into `textValue`. */
  trailing?: ReactNode;
  /** Marks the row unavailable: disabled, on the neutral subtle fill with a muted label, and this
   *  reason at its trailing edge, e.g. "가입 불가". The reason joins the row's accessible name, so a
   *  screen reader hears why the row cannot be chosen, not only that it cannot. */
  unavailableLabel?: string;
  /** The row's accessible name, in place of `textValue`; an `unavailableLabel` reason joins it. */
  "aria-label"?: string;
  /** Additional class. sd-grid-list__item is always retained. */
  className?: string;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function GridListItem<T extends object = object>({
  leading,
  description,
  trailing,
  unavailableLabel,
  className,
  children,
  textValue,
  isDisabled,
  "aria-label": ariaLabel,
  ...props
}: GridListItemProps<T>) {
  const name = textValue || (typeof children === "string" ? children : undefined);
  // A caller's `aria-label` names the row in place of `textValue`, so the reason joins whichever wins.
  const rowName = ariaLabel ?? name;
  return (
    <AriaGridListItem
      {...props}
      textValue={name}
      // The row is named by `aria-label` (React Aria falls back to `textValue`), so the reason joins
      // the name there; the visible reason is then hidden from assistive tech so it is not read twice.
      aria-label={unavailableLabel && rowName ? `${rowName}, ${unavailableLabel}` : ariaLabel}
      isDisabled={isDisabled || unavailableLabel != null}
      data-unavailable={unavailableLabel != null || undefined}
      className={
        className
          ? `sd-grid-list__item sd-type-body-medium ${className}`
          : "sd-grid-list__item sd-type-body-medium"
      }
    >
      {(renderProps) => (
        <>
          {renderProps.selectionMode !== "none" &&
            renderProps.selectionBehavior === "toggle" && (
              <Checkbox slot="selection" className="sd-grid-list__item-selection" />
            )}
          {leading != null && (
            <span className="sd-grid-list__item-leading" aria-hidden="true">
              {leading}
            </span>
          )}
          {/* Everything after the leading slot, as one part: it lays out as nothing of its own
              (`display: contents`) unless the list shares its leading column, where it is the
              row's last track (GridList.css § shared leading column). */}
          <span className="sd-grid-list__item-main">
            {description != null ? (
              <span className="sd-grid-list__item-content">
                <span className="sd-grid-list__item-title sd-type-body-medium">
                  {typeof children === "function" ? children(renderProps) : children}
                </span>
                <Text
                  slot="description"
                  className="sd-grid-list__item-description sd-type-caption-medium"
                >
                  {description}
                </Text>
              </span>
            ) : typeof children === "function" ? (
              children(renderProps)
            ) : typeof children === "string" || typeof children === "number" ? (
              /* Words passed bare take the title part, so a one-line row's label stands one inset
                 in from the row's padding exactly as a two-line row's title does (rule 8). An
                 element the consumer drew carries its own role. */
              <span className="sd-grid-list__item-title sd-type-body-medium">{children}</span>
            ) : (
              children
            )}
            {unavailableLabel != null && (
              <span className="sd-grid-list__item-reason sd-type-caption-medium" aria-hidden="true">
                {unavailableLabel}
              </span>
            )}
            {trailing != null && (
              <span className="sd-grid-list__item-trailing">{trailing}</span>
            )}
          </span>
        </>
      )}
    </AriaGridListItem>
  );
}

export interface GridListSectionProps<T extends object = object>
  extends Omit<AriaGridListSectionProps<T>, "className" | "children"> {
  /** Optional section heading. */
  title?: ReactNode;
  /** GridListItem children or a dynamic collection renderer. */
  children?: AriaGridListSectionProps<T>["children"];
  /** Additional class. sd-grid-list__section is always retained. */
  className?: string;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function GridListSection<T extends object = object>({
  title,
  children,
  className,
  ...props
}: GridListSectionProps<T>) {
  return (
    <AriaGridListSection
      {...props}
      className={
        className ? `sd-grid-list__section ${className}` : "sd-grid-list__section"
      }
    >
      {title && <GridListHeader>{title}</GridListHeader>}
      {typeof children === "function" ? <Collection>{children}</Collection> : children}
    </AriaGridListSection>
  );
}

export interface GridListHeaderProps
  extends Omit<AriaGridListHeaderProps, "className"> {
  /** Additional class. sd-grid-list__section-header is always retained. */
  className?: string;
}

export function GridListHeader({ className, ...props }: GridListHeaderProps) {
  return (
    <AriaGridListHeader
      {...props}
      className={
        className
          // One rung below the items it heads — CONTRASTIVE, per naming-convention.md.
          ? `sd-grid-list__section-header sd-type-label-small ${className}`
          : "sd-grid-list__section-header sd-type-label-small"
      }
    />
  );
}

export interface GridListLoadMoreItemProps
  extends Omit<AriaGridListLoadMoreItemProps, "className" | "children"> {
  /** Loading-row content — required; the .tsx bakes no default text (contract §7b: no
   *  default content, and a hardcoded "Loading…" would ship untranslated English). */
  children: AriaGridListLoadMoreItemProps["children"];
  /** Additional class. sd-grid-list__load-more is always retained. */
  className?: string;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function GridListLoadMoreItem({
  children,
  className,
  isLoading = true,
  ...props
}: GridListLoadMoreItemProps) {
  return (
    <AriaGridListLoadMoreItem
      {...props}
      isLoading={isLoading}
      className={
        className
          ? `sd-grid-list__load-more sd-type-caption-medium ${className}`
          : "sd-grid-list__load-more sd-type-caption-medium"
      }
    >
      {children}
    </AriaGridListLoadMoreItem>
  );
}

.sd-grid-list {
  display: flex;
  flex-direction: column;
  gap: var(--sd-grid-list-gap-current);
  outline: none;
}

/* Grid layout (React Aria's `layout="grid"`, which also gives the arrow keys two dimensions): the
   items flow into as many columns as fit, each no narrower than `minItemWidth` (injected inline by
   the tsx), and each item becomes a tile, its parts stacked, through the `-current` relays below
   (component-contract.md § 6 rule 5). A section lays its own tiles on the same columns and spans
   the list; the load-more row spans it too. An empty list stays a stack, so its empty state keeps
   the full width. The tiles keep the list's own `gap`, which is `0`: an item is unbordered at rest
   and shows its bounds only as the hover, focus and selected paints, so tiles sit flush the way a
   file manager's icon view does.
   Known limit: two selected tiles side by side read as one doubled border. A `grid-list.grid-gap`
   Cmp token is the fix if that case matters. */
.sd-grid-list {
  --sd-grid-list-item-direction-current: row;
  --sd-grid-list-item-align-current: center;
  --sd-grid-list-section-display-current: flex;
  --sd-grid-list-gap-current: var(--sd-grid-list-gap);
  --sd-grid-list-item-background-current: var(--sd-grid-list-item-background);
  --sd-grid-list-item-border-current: var(--sd-grid-list-item-border);
  --sd-grid-list-item-radius-current: var(--sd-grid-list-item-radius);
  --sd-grid-list-item-padding-block-current: var(--sd-grid-list-item-padding-block);
  --sd-grid-list-item-padding-inline-current: var(--sd-grid-list-item-padding-inline);
  --sd-grid-list-item-min-height-current: var(--sd-grid-list-item-min-height);
  /* The hairline over each row but the first: none outside `grouped`. */
  --sd-grid-list-item-divider-current: 0px;
  /* A row is a flex row of its parts, and the part after its leading slot lays out as nothing of its
     own; the shared leading column (below) turns both into grid tracks. */
  --sd-grid-list-item-display-current: flex;
  --sd-grid-list-item-column-current: auto;
  --sd-grid-list-item-main-display-current: contents;
  --sd-grid-list-section-column-gap-current: var(--sd-grid-list-gap);
}
/* contained: each row its own card. The surface pair is spent at one tier (padding and corner both
   `surface.*.medium`, token-contract.md), the edge is the decorative one, and the rows part by the
   card-stack gap. Selected and drop-target paints still override the resting background. */
.sd-grid-list[data-variant="contained"] {
  --sd-grid-list-gap-current: var(--sd-grid-list-contained-gap);
  --sd-grid-list-item-background-current: var(--sd-grid-list-contained-item-background);
  --sd-grid-list-item-border-current: var(--sd-grid-list-contained-item-border);
  --sd-grid-list-item-radius-current: var(--sd-grid-list-contained-item-radius);
  --sd-grid-list-item-padding-block-current: var(--sd-grid-list-contained-item-padding);
  --sd-grid-list-item-padding-inline-current: var(--sd-grid-list-contained-item-padding);
  /* A contained row is a card: a box on its container's line, never pulled out (below). */
  --sd-grid-list-item-outset-current: 0;
}
.sd-grid-list[data-layout="grid"]:not([data-empty]) {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(var(--sd-grid-list-min-item-width), 100%), 1fr));
  /* A section repeats the same tracks. */
  --sd-grid-list-section-columns-current: repeat(auto-fill, minmax(min(var(--sd-grid-list-min-item-width), 100%), 1fr));
  --sd-grid-list-item-direction-current: column;
  --sd-grid-list-item-align-current: stretch;
  --sd-grid-list-section-display-current: grid;
  /* Tiles sit flush on a grid, so none is pulled out (below). */
  --sd-grid-list-item-outset-current: 0;
}

/* Shared leading column (`leadingWidth="shared"`, the stack layout only): the list is one grid whose
   leading track is as wide as the widest row's leading slot, and every row (and every section,
   between them) is a subgrid of it, so the column after the slot starts at one x on every row. The
   tracks are the selection checkbox when the list shows one, the leading slot, and the rest of the
   row as one part (`__item-main`), which is itself the flex row the item is elsewhere. A track only
   exists for a part every row has, so no empty track leaves a stray gap. The tracks part by the
   item's own gap, the gap the flex row spends. Rows stay `role="row"`: this is layout, and React
   Aria's keyboard and ARIA do not read it. The leading part is placed from the end and the checkbox
   takes the first free track, so a row with no leading keeps its text on the shared column.
   Known reach: a drag-and-drop `DropIndicator` is not placed across the tracks. */
.sd-grid-list[data-leading-width="shared"]:not([data-layout="grid"]):not([data-empty]) {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  column-gap: var(--sd-grid-list-item-gap);
  --sd-grid-list-section-display-current: grid;
  --sd-grid-list-section-columns-current: subgrid;
  --sd-grid-list-section-column-gap-current: var(--sd-grid-list-item-gap);
  --sd-grid-list-item-display-current: grid;
  --sd-grid-list-item-column-current: 1 / -1;
  --sd-grid-list-item-main-display-current: flex;
}
.sd-grid-list[data-leading-width="shared"]:not([data-layout="grid"]):not([data-empty]):has(.sd-grid-list__item-selection) {
  grid-template-columns: auto max-content minmax(0, 1fr);
}

.sd-grid-list[data-focus-visible] {
  border-radius: var(--sd-grid-list-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

/* grouped: one box around all the rows, which part by hairlines rather than by gaps or cards, the
   look of a short choice sheet. The box spends the surface pair at the medium tier (its corner here,
   its rows' inline padding below) and clips the rows' paints to its corner. It is a box on its
   container's line, so its rows are never pulled out into a panel's padding (§ outset). After the focus
   rule, whose own corner it keeps. */
.sd-grid-list[data-variant="grouped"] {
  border: var(--sd-grid-list-grouped-border-width) solid var(--sd-grid-list-grouped-border);
  border-radius: var(--sd-grid-list-grouped-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  overflow: hidden;
  --sd-grid-list-item-radius-current: 0;
  --sd-grid-list-item-padding-inline-current: var(--sd-grid-list-grouped-item-padding-inline);
  --sd-grid-list-item-min-height-current: var(--sd-grid-list-grouped-item-min-height);
  --sd-grid-list-item-divider-current: var(--sd-grid-list-grouped-border-width);
  --sd-grid-list-item-outset-current: 0;
}
.sd-grid-list[data-drop-target] {
  background: var(--sd-grid-list-background-drop-target);
}

.sd-grid-list__item {
  position: relative;
  isolation: isolate;
  display: var(--sd-grid-list-item-display-current);
  flex-direction: var(--sd-grid-list-item-direction-current);
  align-items: var(--sd-grid-list-item-align-current);
  gap: var(--sd-grid-list-item-gap);
  /* Read only where the item is a grid (the shared leading column): a subgrid spanning the list. */
  grid-column: var(--sd-grid-list-item-column-current);
  grid-template-columns: subgrid;
  min-height: var(--sd-grid-list-item-min-height-current);
  padding: var(--sd-grid-list-item-padding-block-current) var(--sd-grid-list-item-padding-inline-current);
  /* OUTSET, a 0/1 switch a padded panel sets on its body (Drawer's `__body`) and the root never
     declares for a flat list, so it inherits. Set, a flat row moves out by its padding and edge: its
     text, one inset in from the row's padding as every text stands, lands on the panel title's
     start (one inset in from the panel's), and its box, fill, edge and inset ring bleed into the
     panel's padding together (component-contract.md §6 rule 8). Unset (every other
     context) it is 0 and the row stays a box on its container's line. Contained rows and grid tiles
     declare 0 on the root. Known reach: it inherits through anything nested in that body, a Card
     included, where it aligns the row with that box's own title the same way. */
  margin-inline: calc(var(--sd-grid-list-item-outset-current) * -1 * (var(--sd-grid-list-item-padding-inline-current) + var(--sd-grid-list-item-border-width)));
  background: var(--sd-grid-list-item-background-current);
  color: var(--sd-grid-list-item-foreground);
  border: var(--sd-grid-list-item-border-width) solid var(--sd-grid-list-item-border-current);
  border-radius: var(--sd-grid-list-item-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  cursor: pointer;
  outline: none;
  transition:
    border-color var(--sd-duration-moderate) var(--sd-easing-standard);
  /* The wash each state lays over this part: the surface wash, or over a fill the one named for that
     fill, which goes away from its inks (contrast-contract.mjs § the state layer over a fill). */
  --sd-grid-list-item-state-hover-current: var(--sd-state-hover);
  --sd-grid-list-item-state-pressed-current: var(--sd-state-pressed);
  /* The description's ink, raised to the item's own while the row is hovered or pressed (below). */
  --sd-grid-list-item-description-current: var(--sd-grid-list-item-description-foreground);
}
/* Collection-item interaction (matches ListBox/Menu/Tree): hover/pressed via the
   ::after state-layer tint, focus via the ring — NOT the input border register.
   The rest + selected border are the card look, not interaction feedback. */
.sd-grid-list__item::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-grid-list__item[data-hovered]::after,
.sd-grid-list__item[data-focused]::after {
  background: var(--sd-grid-list-item-state-hover-current);
}
.sd-grid-list__item[data-pressed]::after {
  background: var(--sd-grid-list-item-state-pressed-current);
}
.sd-grid-list__item[data-selected] {
  background: var(--sd-grid-list-item-background-selected);
  border-color: var(--sd-grid-list-item-border-selected);
  --sd-grid-list-item-state-hover-current: var(--sd-state-hover-selected);
  --sd-grid-list-item-state-pressed-current: var(--sd-state-pressed-selected);
}
/* INSET, like every sibling collection row. Two things make outward wrong here rather than merely
   unusual. `item.gap` is `0` ("Rows sit flush
   — a dense list"), so there is no air for an outward ring to paint into and it lands on the
   neighbouring rows; and the moment a consumer bounds the list, `overflow` clips it. `SearchList`
   does exactly that (`max-height` + `overflow-y: auto`, which forces the inline axis to `auto` too),
   which would slice the first row's ring on THREE edges.
   Inset is what `Table__row` does from the same premise — its `focus.ring.width` describes itself as
   "a four-sided inset box-shadow" whose job is to stay legible over the row's own selected and
   drop-target paints, which is this row's case exactly — and what `Dialog__scroll`/`Drawer__scroll`
   do one level up ("the frame's overflow:hidden would clip an outward ring"). `item.radius` already
   said which family this belongs to: "a row, not a card", taking the radius "its five sibling
   collection rows take". Compensating one caller with padding + negative margin would leave the
   gap-0 overlap standing and re-break on the next consumer that bounds a GridList. */
.sd-grid-list__item[data-focus-visible] {
  box-shadow: inset 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-grid-list__item[data-disabled]:not([data-unavailable]) {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}
/* An unavailable row (`unavailableLabel`): disabled, and saying why. It keeps full opacity on the
   neutral subtle fill with a muted label, and the reason stands at its trailing edge, so the row
   reads as present but closed rather than faded out. */
.sd-grid-list__item[data-unavailable] {
  background: var(--sd-grid-list-item-unavailable-background);
  /* The fill's own wash, should a state ever reach a disabled row (contract §6 rule 7). */
  --sd-grid-list-item-state-hover-current: var(--sd-state-hover-neutral-subtle);
  --sd-grid-list-item-state-pressed-current: var(--sd-state-pressed-neutral-subtle);
  color: var(--sd-grid-list-item-unavailable-foreground);
  cursor: not-allowed;
}
.sd-grid-list__item-reason {
  flex: 0 0 auto;
  margin-inline-start: auto;
  color: var(--sd-grid-list-item-reason-foreground);
}
/* The hairline between two rows of a grouped list, drawn on a layer so it never takes the row's
   own edge, which the selected and drop-target paints use. The first row draws none. */
.sd-grid-list__item::before {
  content: "";
  position: absolute;
  inset-block-start: 0;
  inset-inline: 0;
  block-size: var(--sd-grid-list-item-divider-current);
  background: var(--sd-grid-list-grouped-divider);
  pointer-events: none;
}
.sd-grid-list__item:first-child::before {
  content: none;
}
/* drag & drop (dragAndDropHooks): dragged item dims; a valid onto-item drop target
   highlights. Between-item reordering is drawn by DropIndicator. */
.sd-grid-list__item[data-dragging] {
  opacity: var(--sd-state-dragging);
}
.sd-grid-list__item[data-drop-target] {
  background: var(--sd-grid-list-item-background-drop-target);
  border-color: var(--sd-grid-list-item-border-drop-target);
}

/* `section-gap` parts one SECTION from the next and nothing else. Spent as the section's own
   flex `gap` it landed between EVERY child, which pushed the header away from the group it
   labels and toward the group above it — measured in every brand, the header sat closer to the
   previous section's last row than to the first row it names. It also re-spaced the rows
   themselves, so a list's row rhythm changed the moment it gained a header. Rows inside a
   section are now parted by whatever parts rows in a section-less list, which is the root gap. */
.sd-grid-list__section {
  display: var(--sd-grid-list-section-display-current);
  flex-direction: column;
  /* Grid layout only (a flex section ignores both): span the list, and repeat its columns. */
  grid-column: 1 / -1;
  grid-template-columns: var(--sd-grid-list-section-columns-current);
  gap: var(--sd-grid-list-gap);
  column-gap: var(--sd-grid-list-section-column-gap-current);
}

/* ADJACENCY is an assumption, not a guarantee. React Aria's `Virtualizer` wraps each node in a
   `VirtualizerItem`, which would split this pair and silently drop the separation. Nothing under
   `src/**` uses it and no component exposes it, so nothing rendered is wrong; a cold review found
   no selector correct under both shapes at no cost, because spacing an absolutely positioned
   wrapper fights the virtualizer's own layout. Re-measure here first if virtualization is ever
   offered. */
.sd-grid-list__section + .sd-grid-list__section {
  margin-block-start: var(--sd-grid-list-section-gap);
}

.sd-grid-list__section-header {
  /* Grid layout: the header heads the whole row of tiles, not one cell. */
  grid-column: 1 / -1;
  padding-block: var(--sd-grid-list-section-header-padding-block-start) var(--sd-grid-list-section-header-padding-block-end);
  padding-inline: var(--sd-grid-list-section-header-padding-inline);
  color: var(--sd-grid-list-section-header-foreground);
}

.sd-grid-list__load-more {
  display: flex;
  grid-column: 1 / -1;
  justify-content: center;
  padding-block: var(--sd-grid-list-load-more-padding-block);
  padding-inline: var(--sd-grid-list-load-more-padding-inline);
  color: var(--sd-grid-list-load-more-foreground);
}

/* Generic leading slot — holds an icon, number, avatar, image, or swatch. It hugs its
   content (no forced width/height, so an avatar/image/number sizes itself) and never
   shrinks. `font-size` sets the default glyph size so a bare `1em` icon lands at
   icon-medium; richer content overrides its own dimensions. */
.sd-grid-list__item-leading {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  font-size: var(--sd-grid-list-item-leading-size);
  /* Read only in the shared leading column: the slot is the track before the row's last one, and
     its content starts the track, so a shorter value stands where a longer one starts. */
  grid-column: -3 / -2;
  justify-self: start;
}

/* Everything after the leading slot. Elsewhere it lays out as nothing of its own (`display:
   contents`), so its parts are the row's flex items as before; in the shared leading column it is
   the row's last track and the same flex row of them. */
.sd-grid-list__item-main {
  display: var(--sd-grid-list-item-main-display-current);
  grid-column: -2 / -1;
  align-items: center;
  gap: var(--sd-grid-list-item-gap);
  min-width: 0;
}

/* Rich two-line row: the text stack takes the remaining width (min-width:0 so long
   title/description truncate instead of shoving the trailing accessory off the row). */
.sd-grid-list__item-content {
  display: flex;
  flex-direction: column;
  gap: var(--sd-grid-list-item-content-gap);
  flex: 1 1 auto;
  min-width: 0;
}

/* Primary label — declares the item's own `body-medium` role again, and inherits only the
   foreground. Without a description the children render straight under the item, at that same
   role, so the two shapes read identically. */
.sd-grid-list__item-title {
  color: inherit;
}

/* Secondary line — caption role (applied via the type class) recoloured muted. */
.sd-grid-list__item-description {
  color: var(--sd-grid-list-item-description-current);
}

/* Trailing accessory (chevron / metadata / action) pinned to the row end. */
.sd-grid-list__item-trailing {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  margin-inline-start: auto;
  color: var(--sd-grid-list-item-trailing-foreground);
  font-size: var(--sd-grid-list-item-trailing-size);
}

/* Raised to the row's own ink while it is hovered or pressed: this ink is derived at its floor and
   falls under 4.5:1 over the surface wash (contrast-contract.mjs § SURFACE_WASH_INKS). */
.sd-grid-list__item[data-hovered],
.sd-grid-list__item[data-pressed] {
  --sd-grid-list-item-description-current: var(--sd-grid-list-item-foreground);
}

/* The empty-state message (`renderEmptyState`): its own text part, so it takes a type role and the
   text inset like every other text, in the supporting ink of an empty line. */
.sd-grid-list__empty {
  color: var(--sd-grid-list-empty-foreground);
}
